Proof.
ltac2:(KReplay.run1 (kr_t_BothSmear ()) [] "p'0h01Hh11bi001bh21Eh32H0h41ah51ep;1p;3p;2p;6p;7g0000j1;Tg00@kj1:Tg00^Lj16Tg01Bhj14Tg01ODj31Tg00:jj32Tg01P1j25Tg00C7j63j78Tg01Q2j27Tg00=Rj19Tg00PQR0f0R1g00k5R232p=0g00Nd#;#:#6R3#4R4f1R5=131#0f2R6=245R7P4f3R8f4R9=131#0g00QQR:]0X14A1388#0P0A1399%01X10P1g00Q1R81539E3A2082P0P8P0p-0P1g00OIP:n0110000020000X50g01<NP2P1E3P:17:1b3b0W0P6P1P5F8W2%97eW0X14W4o"). Qed.
Local Ltac getr_proof X r :=
  lazymatch X with
  | regupd ?Y ?rd ?v =>
      match tt with
      | _ => let chk := match tt with _ => constr_eq rd r end in
             uconstr:(getr_same Y r v (reg_neq_of_eqb r (0%bv) (@eq_refl bool false)))
      | _ => let p := getr_proof Y r in
             uconstr:(eq_trans (getr_other Y rd v r (reg_neq_of_eqb r rd (@eq_refl bool false))) p)
      end
  | _ => uconstr:(@eq_refl word (getr X r))
  end.
Local Ltac gres :=
  repeat match goal with
         | |- context [getr ?X ?r] =>
             lazymatch X with regupd _ _ _ => idtac end;
             let p := getr_proof X r in
             let p' := constr:(p) in rewrite p'
         end.

